def check(it, cache):
    import os, re
    if it["id"] not in EV:
        return None
    f, q = EV[it["id"]]
    p = os.path.join(cache, f)
    if not os.path.exists(p):
        return None
    # Compare letters and digits only: lawphil pages carry stray cp1252 quote bytes and "lawphi1.net" watermarks.
    n = lambda s: " ".join(re.sub(r"[^a-z0-9]+", " ", s.lower().replace("lawphi1.net", " ").replace("lawphil.net", " ")).split())
    return n(q) in n(open(p, encoding="utf-8", errors="ignore").read())
